using System.Text.Json;
using Avalonia;
using Avalonia.Automation;
using Avalonia.Automation.Peers;
using Avalonia.Controls;
using Avalonia.Controls.ApplicationLifetimes;
using Avalonia.Headless;
using Avalonia.Input;
using Avalonia.Media;
using Avalonia.Media.Imaging;
using Avalonia.Threading;
using Verifier.Desktop;
internal sealed class CapabilityHeaderProbeApplication:Application
{
 private sealed record Case(string Id,bool English,double[] Columns);
 public override void OnFrameworkInitializationCompleted()
 {
  var life=(IClassicDesktopStyleApplicationLifetime)ApplicationLifetime!;var args=life.Args!;var cases=JsonSerializer.Deserialize<Case[]>(File.ReadAllText(args[1]),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;var output=args[2];Directory.CreateDirectory(output);
  var header=new WebCapabilityHeader();var canvas=new Canvas{Width=1200,Height=800,Background=Brush.Parse("#2b2d31"),UseLayoutRounding=false};canvas.Children.Add(header);Canvas.SetLeft(header,30);Canvas.SetTop(header,60);var window=new Window{Title="Replica CapabilityHeader verification",Width=1250,Height=850,Content=canvas,UseLayoutRounding=false};life.MainWindow=window;
  object Box(Control c){var p=c.TranslatePoint(default,header)??default;return new{x=p.X,y=p.Y,width=c.Bounds.Width,height=c.Bounds.Height};}
  void Set(Case c){header.SetEnglish(c.English);header.ColumnWidths=c.Columns;window.UpdateLayout();}
  if(args[0]=="--capabilityheader-window"){
   Set(cases.Single(c=>c.Id=="ko-904"));var narrow=false;var text=new TextBlock{Width=1100,TextWrapping=TextWrapping.Wrap};Canvas.SetLeft(text,30);Canvas.SetTop(text,600);canvas.Children.Add(text);
   void State(){window.UpdateLayout();var focus=window.FocusManager?.GetFocusedElement() as Control;var state=new{english=header.English,attached=canvas.Children.Contains(header),narrow,focused=focus is null?"":AutomationProperties.GetAutomationId(focus)??"",width=canvas.Children.Contains(header)?header.Bounds.Width:0,height=canvas.Children.Contains(header)?header.Bounds.Height:0,texts=header.Labels.Select(t=>t.Text).ToArray(),background=header.HeaderBackground?.ToString()};var json=JsonSerializer.Serialize(state);text.Text=json;File.WriteAllText(Path.Combine(output,"capabilityheader-input.json"),json);}
   void Utility(string id,double x,Action action){var button=new Button{Content=id,MinHeight=44,Padding=new(12,8)};AutomationProperties.SetAutomationId(button,"CapabilityHeader-"+id);button.Click+=(_,_)=>{action();Dispatcher.UIThread.Post(State);};Canvas.SetLeft(button,x);canvas.Children.Add(button);}
   Utility("language",400,()=>Set(cases.Single(c=>c.Id==(header.English?"ko":"en")+"-"+(narrow?478:904))));Utility("width",530,()=>{narrow=!narrow;Set(cases.Single(c=>c.Id==(header.English?"en":"ko")+"-"+(narrow?478:904)));});Utility("mount",660,()=>{if(canvas.Children.Contains(header))canvas.Children.Remove(header);else canvas.Children.Add(header);});
   window.AddHandler(InputElement.GotFocusEvent,(_,_)=>Dispatcher.UIThread.Post(State),Avalonia.Interactivity.RoutingStrategies.Bubble,true);window.AddHandler(InputElement.LostFocusEvent,(_,_)=>Dispatcher.UIThread.Post(State),Avalonia.Interactivity.RoutingStrategies.Bubble,true);header.PointerPressed+=(_,_)=>Dispatcher.UIThread.Post(State);window.Opened+=(_,_)=>Dispatcher.UIThread.Post(State);
  }else window.Opened+=(_,_)=>Dispatcher.UIThread.Post(async()=>{
   if(args.Contains("--names-only")){
    var names=new List<object>();foreach(var id in new[]{"ko-904","en-904"}){Set(cases.Single(c=>c.Id==id));var peers=ControlAutomationPeer.CreatePeerForElement(header)!.GetChildren()!;var labels=header.Labels.Select(t=>t.Text).ToArray();if(OperatingSystem.IsWindows()&&(!peers.Select(p=>p.GetName()).SequenceEqual(labels)||peers.Any(p=>(p.GetChildren()?.Count??0)!=0)))throw new InvalidOperationException("Windows source header names missing");names.Add(new{id,names=peers.Select(p=>p.GetName()).ToArray(),children=peers.Select(p=>(p.GetChildren()??Array.Empty<AutomationPeer>()).Select(c=>c.GetName()).ToArray()).ToArray()});}
    canvas.Children.Remove(header);window.UpdateLayout();canvas.Children.Add(header);window.UpdateLayout();var remounted=ControlAutomationPeer.CreatePeerForElement(header)!.GetChildren()!;if(OperatingSystem.IsWindows()&&(!remounted.Select(p=>p.GetName()).SequenceEqual(header.Labels.Select(t=>t.Text))||remounted.Any(p=>(p.GetChildren()?.Count??0)!=0)))throw new InvalidOperationException("Windows header names missing after remount");names.Add(new{id="remount",names=remounted.Select(p=>p.GetName()).ToArray(),children=remounted.Select(p=>(p.GetChildren()??Array.Empty<AutomationPeer>()).Select(c=>c.GetName()).ToArray()).ToArray()});File.WriteAllText(Path.Combine(output,"capabilityheader-names.json"),JsonSerializer.Serialize(new{dpr=window.RenderScaling,states=names}));window.Close();Console.WriteLine("Recorded 3 changed Header name states");return;
   }
   var rows=new List<object>();foreach(var c in cases){Set(c);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);window.UpdateLayout();var peer=ControlAutomationPeer.CreatePeerForElement(header)!;var children=peer.GetChildren()!;if(peer.GetClassName()!="Row"||children.Count!=4||children.Any(p=>p.GetClassName()!="ColumnHeader"||p.GetAutomationControlType()!=AutomationControlType.HeaderItem||(p.GetChildren()?.Count??0)!=(OperatingSystem.IsWindows()?0:1)))throw new InvalidOperationException("Literal four-header tree missing");rows.Add(new{id=c.Id,root=Box(header),cells=header.Cells.Select((cell,i)=>new{box=Box(cell),text=header.Labels[i].Text,textLayout=Box(header.Labels[i]),lineWidths=header.Labels[i].SystemLineWidths,lineTexts=header.Labels[i].SystemLineTexts,fontSize=header.Labels[i].FontSize,fontWeight=(int)header.Labels[i].FontWeight,lineHeight=header.Labels[i].LineHeight,color=header.Labels[i].Foreground?.ToString(),background=header.HeaderBackground?.ToString(),border=header.HeaderBorder?.ToString(),padding=new[]{12,18},textAlign=i is 1 or 2?"center":"left",peerType=children[i].GetAutomationControlType().ToString(),peerRole=children[i].GetClassName(),peerName=children[i].GetName(),childNames=(children[i].GetChildren()??Array.Empty<AutomationPeer>()).Select(p=>p.GetName()).ToArray()}).ToArray()});if(c.Id is "ko-478" or "en-904"){using var image=new RenderTargetBitmap(new PixelSize(2400,1600),new Vector(192,192));image.Render(canvas);image.Save(Path.Combine(output,"capabilityheader-"+c.Id+".png"),new PngBitmapEncoderOptions());}}
   File.WriteAllText(Path.Combine(output,"capabilityheader-native.json"),JsonSerializer.Serialize(new{dpr=window.RenderScaling,headers=rows},new JsonSerializerOptions{WriteIndented=true}));
   if(ReplicaPlatform.IsHeadless){var states=new List<object>();var utility=new Button{Content="focus",Width=100,Height=44};AutomationProperties.SetAutomationId(utility,"CapabilityHeader-headless-focus");canvas.Children.Add(utility);window.Activate();Set(cases.Single(c=>c.Id=="en-904"));window.UpdateLayout();utility.Focus();var point=header.Cells[0].TranslatePoint(new(header.Cells[0].Bounds.Width/2,header.Cells[0].Bounds.Height/2),window)!.Value;window.MouseMove(point);window.MouseDown(point,MouseButton.Left);window.MouseUp(point,MouseButton.Left);await Dispatcher.UIThread.InvokeAsync(()=>{},DispatcherPriority.Background);if(window.FocusManager?.GetFocusedElement()!=null)throw new InvalidOperationException("Passive header did not blur prior button");states.Add(new{id="source-passive-english",focused="",width=header.Bounds.Width,texts=header.Labels.Select(t=>t.Text).ToArray()});foreach(var id in new[]{"en-478","ko-478","ko-904"}){Set(cases.Single(c=>c.Id==id));states.Add(new{id,width=header.Bounds.Width,texts=header.Labels.Select(t=>t.Text).ToArray()});}canvas.Children.Remove(header);window.UpdateLayout();states.Add(new{id="detach",attached=false});canvas.Children.Add(header);window.UpdateLayout();if(ControlAutomationPeer.CreatePeerForElement(header)!.GetChildren()?.Count!=4)throw new InvalidOperationException("Header peer missing after remount");states.Add(new{id="remount",attached=true});using(var image=window.CaptureRenderedFrame()??throw new InvalidOperationException("Real rendered frame missing"))image.Save(Path.Combine(output,"capabilityheader-headless-input.png"),new PngBitmapEncoderOptions());File.WriteAllText(Path.Combine(output,"capabilityheader-headless-input.json"),JsonSerializer.Serialize(new{states}));}
   window.Close();Console.WriteLine("Recorded "+rows.Count+" Capability headers");},DispatcherPriority.Background);
  base.OnFrameworkInitializationCompleted();
 }
}
